class Solution:
    def possibleStringCount(self, word: str, k: int) -> int:
        MOD = 1_000_000_007
        groups = []
        curr = 1
        for i in range(1, len(word)):
            if word[i] == word[i - 1]:
                curr += 1
            else:
                groups.append(curr)
                curr = 1
        groups.append(curr)

        total = 1
        for c in groups:
            total = (total * c) % MOD

        m = len(groups)
        if k <= m:
            return total

        limit = k - m - 1
        dp = [0] * (limit + 1)
        dp[0] = 1

        for c in groups:
            max_y = c - 1
            pref = [0] * (limit + 2)
            for j in range(limit + 1):
                pref[j + 1] = (pref[j] + dp[j]) % MOD
            new_dp = [0] * (limit + 1)
            for s in range(limit + 1):
                low = max(0, s - max_y)
                new_dp[s] = (pref[s + 1] - pref[low]) % MOD
            dp = new_dp

        invalid = sum(dp) % MOD
        return (total - invalid + MOD) % MOD

class Solution {
public:
    int possibleStringCount(string word, int k) {
        const long long MOD = 1000000007;
        vector<int> groups;
        int curr = 1;
        for (int i = 1; i < (int)word.size(); ++i) {
            if (word[i] == word[i - 1]) {
                curr++;
            } else {
                groups.push_back(curr);
                curr = 1;
            }
        }
        groups.push_back(curr);

        long long total = 1;
        for (int c : groups) {
            total = (total * c) % MOD;
        }

        int m = groups.size();
        if (k <= m) return total;

        int limit = k - m - 1;
        vector<long long> dp(limit + 1, 0);
        dp[0] = 1;

        for (int c : groups) {
            int max_y = c - 1;
            vector<long long> pref(limit + 2, 0);
            for (int j = 0; j <= limit; ++j) {
                pref[j + 1] = (pref[j] + dp[j]) % MOD;
            }
            vector<long long> new_dp(limit + 1, 0);
            for (int s = 0; s <= limit; ++s) {
                int low = max(0, s - max_y);
                new_dp[s] = (pref[s + 1] - pref[low] + MOD) % MOD;
            }
            dp = std::move(new_dp);
        }

        long long invalid = 0;
        for (long long v : dp) invalid = (invalid + v) % MOD;
        return (total - invalid + MOD) % MOD;
    }
};

