        }

        int m = groups.size();
        if (k <= m) return (int) total;

        int limit = k - m - 1;
        long[] dp = new long[limit + 1];
        dp[0] = 1;

        for (int c : groups) {
            int maxY = c - 1;
            long[] pref = new long[limit + 2];
            for (int j = 0; j <= limit; j++) {
                pref[j + 1] = (pref[j] + dp[j]) % MOD;
            }
            long[] newDp = new long[limit + 1];
